'use strict';
const screen=document.querySelector('#screen'), selector=document.querySelector('#state');
const icons={link:'<path d="M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2"/><path d="M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2"/>',signal:'<path d="M12 12v9M8 8a6 6 0 0 0 0 8m8-8a6 6 0 0 1 0 8M5 5a10 10 0 0 0 0 14M19 5a10 10 0 0 1 0 14"/><circle cx="12" cy="10" r="1.6"/>',qr:'<path d="M3 8V3h5m8 0h5v5M3 16v5h5m8 0h5v-5"/><rect x="7" y="7" width="3" height="3"/><rect x="14" y="7" width="3" height="3"/><rect x="7" y="14" width="3" height="3"/><path d="M14 14h3v3h-3z"/>',wave:'<path d="M4 10v4m4-7v10m4-14v18m4-14v10m4-7v4"/>',back:'<path d="m15 4-8 8 8 8"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]}</svg>`;
const states={new:'连接手办',ready:'可互动',listening:'正在听',waiting:'处理中',playing:'正在回应',busy:'互动进行中',stale:'等待状态更新',offline:'未连接',error:'暂时无法互动'};
let result='',working=false,refreshTimer;
const chosen=()=>selector.value;
const isSet=()=>chosen()!=='new';
function nav(title,back='home'){return `<div class="navhead"><button class="back" data-route="${back}" aria-label="返回">${icon('back')}返回</button><h2>${title}</h2></div>`;}
function row(label,value){return `<div class="row"><span>${label}</span><span>${value}</span></div>`;}
function action(label,route,cls=''){return `<button class="row-button ${cls}" data-route="${route}">${label}<span>›</span></button>`;}
function home(){const connected=isSet();return `<div class="page"><div class="head"><div><h1>小鲸</h1><p>日常搭子</p></div><button class="icon" data-route="connect" aria-label="连接设置">${icon('link')}</button></div><button class="state-row" data-route="device">${icon(connected?'signal':'link')}<span>${states[chosen()]}</span><small>›</small></button><div class="hero"><img src="/ios/AIFigure/Resources/Assets.xcassets/XiaojingFront.imageset/front.png" alt="小鲸正面形象"></div>${connected?`<button class="primary" id="identify" ${chosen()!=='ready'||working?'disabled':''}>${icon('wave')}${working?'等待手办回应':'识别手办'}</button><p class="hint">按住手办按键说话，松开后听回应</p>`:`<button class="primary" data-route="scan">${icon('qr')}扫码连接手办</button><button class="secondary" data-route="connect">手动连接</button>`}${result?`<div class="result">${result}</div>`:''}${chosen()==='error'?'<p class="message">暂时连不上设备服务，请检查Wi-Fi与电脑服务</p>':''}${chosen()==='offline'?'<p class="message">按一下手办按键，等待连接</p>':''}</div>`;}
function device(){const online=!['new','offline'].includes(chosen());return `<div class="list-page">${nav('我的手办')}<div class="list-body"><p class="section-label">当前状态</p><div class="group">${row('手办',states[chosen()])}${row('供电',online?'已接电源':'供电状态未知')}${row('电量','暂不可用')}${row('最后状态更新',online?'刚刚':'暂无新记录')}${result?row('执行结果',result):''}<button class="row-button" id="refresh">刷新状态</button></div><p class="section-label">连接</p><div class="group">${action('连接设置','connect')}${action('Wi-Fi配网','wifi')}${isSet()?'<button class="row-button danger" id="disconnect">断开并清除连接</button>':''}</div><p class="section-label">帮助信息</p><div class="group">${row('设备',isSet()?'c3-lab-01':'未连接')}${row('固件',isSet()?'0.5.10-selftest-adc':'未知')}</div><p class="footnote">这是局域网设备试用版。连接码保存在本机钥匙串，手机与手办需能访问同一台电脑服务。</p></div></div>`;}
function connect(){return `<div class="list-page"><div class="navhead"><h2>连接设置</h2><button class="done" data-route="home">完成</button></div><div class="list-body"><p class="section-label">连接手办</p><form class="group" id="connect-form"><input class="field" aria-label="服务器地址" inputmode="url" value="http://192.168.137.1:8795" autocomplete="off" ${isSet()?'disabled':''}><input class="field" id="credential" type="password" aria-label="连接凭据" placeholder="连接凭据" autocomplete="off" ${isSet()?'disabled':''}>${isSet()?'<button type="button" class="submit" id="disconnect">断开并重新设置</button>':'<button class="submit" id="connect-submit" disabled>连接</button>'}</form><p class="footnote">连接码由电脑上的手办服务提供。手机需接入同一局域网，并允许本地网络访问。</p></div></div>`;}
function wifi(){return `<div class="list-page">${nav('Wi-Fi配网','device')}<div class="list-body"><p class="section-label">配置网络</p><div class="group">${['搜索设备','连接手办','建立安全连接','写入Wi-Fi名称与密码','确认联网结果'].map((v,i)=>`<div class="step"><i>${i+1}</i>${v}</div>`).join('')}</div><p class="section-label">附近的手办</p><div class="group"><button class="row-button" id="scan-ble">搜索设备</button></div><p class="footnote" id="ble-note">请开启蓝牙，并让手办进入配网模式。</p></div></div>`;}
function scan(){return `<div class="scan"><div class="navhead"><h2>扫描连接码</h2><button class="done" data-route="home">取消</button></div><div class="scanbox"></div><p>将连接码放入框内</p></div>`;}
function toast(text){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.textContent=text;document.querySelector('.phone').append(t);setTimeout(()=>t.remove(),2200);}
function render(){const route=location.hash.slice(1)||'home';screen.innerHTML=({home,device,connect,wifi,scan}[route]||home)();screen.scrollTop=0;document.querySelectorAll('aside button').forEach(b=>b.classList.toggle('chosen',b.dataset.route===route));document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>location.hash=b.dataset.route));document.querySelector('#identify')?.addEventListener('click',()=>{working=true;result='正在等待手办回执';render();refreshTimer=setTimeout(()=>{working=false;result='识别已完成';render();},1100)});document.querySelector('#disconnect')?.addEventListener('click',()=>{clearTimeout(refreshTimer);working=false;selector.value='new';result='';location.hash='home';render()});document.querySelector('#refresh')?.addEventListener('click',()=>toast('预览：状态已刷新'));document.querySelector('#credential')?.addEventListener('input',e=>{document.querySelector('#connect-submit').disabled=!e.target.value.trim()});document.querySelector('#connect-form')?.addEventListener('submit',e=>{e.preventDefault();selector.value='ready';result='';location.hash='home'});document.querySelector('#scan-ble')?.addEventListener('click',()=>{document.querySelector('#ble-note').textContent='请在iPhone中开启蓝牙后搜索设备。'});}
selector.addEventListener('change',()=>{clearTimeout(refreshTimer);working=false;result='';render()});window.addEventListener('hashchange',render);render();
